/**
 * Bulk import: column specs + validation rules.
 *
 * Single source of truth for BOTH the templates in /imports (generated by
 * scripts/generate-import-templates.js, which compiles this file) and the
 * import API/UI, so a column can never exist in one and not the other.
 *
 * Everything imports as NOT accepted: `status` is forced to 'pending' and is
 * deliberately not an importable column — a typo must never be able to approve
 * someone. Passwords are not set here either; they are generated and emailed
 * on approval (see mdfiles/acceptance-credentials-email.md).
 */
import { CHALLENGES } from './challenges';

export type EntityKey = 'teams' | 'participants' | 'mentors' | 'teams-with-leader';

export interface ColumnSpec {
  /** Exact Prisma field name — used verbatim as the CSV/Excel header. */
  key: string;
  labelAr: string;
  required: boolean;
  type: 'string' | 'boolean';
  /** Value must be one of these (case/space-insensitive) when provided. */
  oneOf?: readonly string[];
  /** A value outside `oneOf` warns instead of failing the row. */
  softOneOf?: boolean;
  note: string;
}

export const PROFESSIONAL_FIELDS = ['ذكاء اصناعي', 'علم البيانات', 'برمجة'] as const;
