export const headersFor = (entity: EntityKey): string[] =>
  IMPORT_SPECS[entity].columns.map((c) => c.key);

/** Loose truthy/falsey parsing so نعم/لا, 1/0 and TRUE/FALSE all work. */
export function parseBoolean(raw: string): boolean | null {
  const v = raw.trim().toLowerCase();
  if (v === '') return null;
  if (['true', '1', 'yes', 'y', 'نعم', 'صح'].includes(v)) return true;
  if (['false', '0', 'no', 'n', 'لا', 'خطأ'].includes(v)) return false;
  return null;
}
/** Distinguishes "not provided" from "provided but unparseable". */
export const isBooleanLike = (raw: string): boolean =>
  raw.trim() === '' || parseBoolean(raw) !== null;

export const normalizeEmail = (raw: string): string => raw.trim().toLowerCase();

export function isValidEmail(raw: string): boolean {
  const v = raw.trim();
  return v.length > 3 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
}
